  const SIZES = [36, 38, 40, 42, 44];
  const HIGHLIGHTS_SHORT = [
    'Vaira Oosi Design',
    'Premium Soft Silk',
    'Festivals & Functions'
  ];

  /* ── RENDER GRID ── */
  function renderGrid(prods) {
    const grid = document.getElementById('productsGrid');
    grid.innerHTML = prods.map((p, i) => `
      <div class="prod-card" onclick="openDetail(${i})">
        <div class="card-img-wrap">
          <img src="${p.img}" alt="${p.name} - ${p.colour}" loading="lazy"/>
          ${p.badge ? `<span class="card-badge ${p.badge.toLowerCase()}">${p.badge}</span>` : ''}
          <button class="heart-btn" onclick="event.stopPropagation();toggleHeart(this)" aria-label="Wishlist">♡</button>
          <span class="free-ship">Free TN Ship</span>
        </div>
        <div class="card-body">
          <div class="card-colour">Couple Combo · ${p.colour}</div>
          <div class="card-name">Vaira Oosi Design – Soft Silk Saree</div>
          <div class="card-highlights">
            ${HIGHLIGHTS_SHORT.map(h => `<div class="card-hl">${h}</div>`).join('')}
          </div>
          <div class="card-sizes">
            <div class="sizes-lbl">Shirt Size</div>
            <div class="size-chips">
              ${SIZES.map(s => `<span class="size-chip" onclick="event.stopPropagation();selectSize(this,'card-${i}')">${s}</span>`).join('')}
            </div>
          </div>
          <div class="card-price-row">
            <div>
              <div class="card-price">₹1,250</div>
              <div><span class="card-mrp">₹1,800</span> &nbsp;<span class="card-off">31% off</span></div>
            </div>
          </div>
          <button class="add-cart-btn" id="cart-${p.id}" onclick="event.stopPropagation();quickAdd('${p.id}','${p.name} (${p.colour})','${p.img}')">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle;margin-right:5px"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>Add to Cart
          </button>
        </div>
      </div>
    `).join('');
  }

  renderGrid(PRODUCTS);

  /* ── SIZE SELECTION ── */
  function selectSize(el, group) {
    el.closest('.size-chips').querySelectorAll('.size-chip').forEach(c => c.classList.remove('selected'));
    el.classList.add('selected');
  }

  /* ── SORT ── */
  function sortProducts() {
    const val = document.getElementById('sortSelect').value;
    let sorted = [...PRODUCTS];
    if (val === 'price-low')  sorted.sort((a,b) => a.price - b.price);
    if (val === 'price-high') sorted.sort((a,b) => b.price - a.price);
    renderGrid(sorted);
  }

  /* ── WISHLIST ── */
  function saveWishlist(list) { localStorage.setItem('kvb_wishlist', JSON.stringify(list)); }
  function loadWishlist() { try { return JSON.parse(localStorage.getItem('kvb_wishlist') || '[]'); } catch(e) { return []; } }

  function toggleHeart(btn) {
    const liked = btn.classList.toggle('liked');
    btn.textContent = liked ? '♥' : '♡';
    const card = btn.closest('.prod-card');
    const name = card ? (card.querySelector('.card-name')?.textContent || '') : '';
    const img  = card ? (card.querySelector('img')?.src || '') : '';
        const safeId = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    const id = name ? safeId(name) + '-' + safeId(card.querySelector('.card-colour')?.textContent || '') : ('cc-' + [...document.querySelectorAll('.heart-btn')].indexOf(btn));
    btn.dataset.id = id;
    let wl = loadWishlist();
    if (liked) { if (!wl.some(i => i.id === id)) wl.push({ id, name, cat: 'Couple Combo', img }); }
    else { wl = wl.filter(i => i.id !== id); }
    saveWishlist(wl);
  }

  /* ── QUICK ADD ── */
  function quickAdd(id, name, img) {
    const btn = document.getElementById('cart-' + id);
    const cardBody = btn && btn.closest('.card-body');
    const selectedChip = cardBody && cardBody.querySelector('.size-chip.selected');
    if (!selectedChip) {
      const lbl = cardBody && cardBody.querySelector('.sizes-lbl');
      if (lbl) {
        lbl.textContent = '⚠ Please select a size!';
        lbl.style.color = '#c0392b';
        setTimeout(() => { lbl.textContent = 'Shirt Size'; lbl.style.color = ''; }, 2500);
      }
      return;
    }
    const size = selectedChip.textContent;
    addToCart(id + '-' + size, name, 1250, 'Couple Combo', img, size);
    if (btn) { btn.textContent = '✓ Added!'; btn.classList.add('added'); setTimeout(() => { btn.textContent = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle;margin-right:5px"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>Add to Cart'; btn.classList.remove('added'); }, 2000); }
  }

  /* ── DETAIL MODAL ── */
  let currentDetailIdx = 0;
  function openDetail(idx) {
    currentDetailIdx = idx;
    const p = PRODUCTS[idx];
    document.getElementById('detailMainImg').src = p.img;
    document.getElementById('detailName').textContent = 'Vaira Oosi Design – Soft Silk Saree';
    document.getElementById('detailColour').textContent = 'Colour: ' + p.colour;

    // thumbnails
    const thumbsEl = document.getElementById('galleryThumbs');
    thumbsEl.innerHTML = PRODUCTS.map((tp, ti) => `
      <div class="thumb ${ti === idx ? 'active' : ''}" onclick="switchImg(${ti})">
        <img src="${tp.img}" alt="Variant ${ti+1}" loading="lazy"/>
      </div>
    `).join('');

    // sizes
    const sizesEl = document.getElementById('detailSizes');
    sizesEl.innerHTML = SIZES.map(s => `<span class="detail-size-chip" onclick="selectDetailSize(this)">${s}</span>`).join('');

    document.getElementById('detailModal').classList.add('show');
    document.body.style.overflow = 'hidden';
  }

  function switchImg(idx) {
    currentDetailIdx = idx;
    document.getElementById('detailMainImg').src = PRODUCTS[idx].img;
    document.querySelectorAll('#galleryThumbs .thumb').forEach((t,i) => t.classList.toggle('active', i===idx));
  }

  function closeDetail() {
    document.getElementById('detailModal').classList.remove('show');
    document.body.style.overflow = '';
  }

  function selectDetailSize(el) {
    document.querySelectorAll('.detail-size-chip').forEach(c => c.classList.remove('selected'));
    el.classList.add('selected');
  }

  function addFromDetail() {
    const p = PRODUCTS[currentDetailIdx];
    const selectedSize = document.querySelector('.detail-size-chip.selected');
    const size = selectedSize ? selectedSize.textContent : 'N/A';
    addToCart(p.id + '-' + size, `Vaira Oosi (${p.colour}, Size ${size})`, 1250, 'Couple Combo', p.img, size);
    const btn = document.getElementById('detailAddBtn');
    btn.textContent = '✓ Added to Cart!';
    setTimeout(() => { btn.textContent = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle;margin-right:5px"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>Add to Cart'; closeDetail(); }, 1000);
  }

  function enquireDetail() {
    const p = PRODUCTS[currentDetailIdx];
    const selectedSize = document.querySelector('.detail-size-chip.selected');
    const size = selectedSize ? selectedSize.textContent : 'N/A';
    const msg = `Hello KVB Sarees! I am interested in the Couple Combo - Vaira Oosi Design (${p.colour}, Shirt Size ${size}). Price: ₹1,250. Please confirm availability.`;
    window.open(`https://wa.me/${OWNER_WA}?text=${encodeURIComponent(msg)}`, '_blank', 'noopener');
  }

  /* ── CART ── */
  function saveCart() { localStorage.setItem('kvb_cart', JSON.stringify(cart)); }
  function loadCart() { try { return JSON.parse(localStorage.getItem('kvb_cart') || '[]'); } catch(e) { return []; } }

  let cart = loadCart();
  let currentOrderId = '';

  renderCart();
  document.getElementById('cartBadge').textContent = cart.reduce((s,i)=>s+i.qty,0) || '0';

  function addToCart(id, name, price, category, img, size) {
    const existing = cart.find(i => i.id === id);
    if (existing) { existing.qty++; }
    else { cart.push({ id, name, price, category, img, size, qty: 1 }); }
    saveCart();
    renderCart();
    const b = document.getElementById('cartBadge');
    b.textContent = cart.reduce((s,i) => s+i.qty, 0);
    showToast(name);
  }

  let toastTimer;
  function showToast(name) {
    let t = document.getElementById('ccToast');
    if (!t) {
      t = document.createElement('div');
      t.id = 'ccToast';
      t.setAttribute('role','status');
      t.style.cssText = 'position:fixed;bottom:2rem;left:50%;transform:translateX(-50%) translateY(20px);background:#1a5c2a;color:#fff;padding:.65rem 1.4rem;border-radius:40px;font-size:.85rem;font-weight:600;box-shadow:0 8px 32px rgba(26,92,42,.25);z-index:5000;opacity:0;transition:opacity .3s,transform .3s;white-space:nowrap;max-width:90vw;overflow:hidden;text-overflow:ellipsis;pointer-events:none;';
      document.body.appendChild(t);
    }
    const short = name.length > 40 ? name.slice(0,38)+'…' : name;
    t.textContent = '✓ Added: ' + short;
    t.style.opacity = '1';
    t.style.transform = 'translateX(-50%) translateY(0)';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { t.style.opacity='0'; t.style.transform='translateX(-50%) translateY(20px)'; }, 2500);
  }

  function updateQty(id, delta) {
    const item = cart.find(i => i.id === id);
    if (!item) return;
    item.qty += delta;
    if (item.qty <= 0) cart = cart.filter(i => i.id !== id);
    saveCart();
    renderCart();
    document.getElementById('cartBadge').textContent = cart.reduce((s,i)=>s+i.qty,0);
  }

  function removeItem(id) {
    cart = cart.filter(i => i.id !== id);
    saveCart();
    renderCart();
    document.getElementById('cartBadge').textContent = cart.reduce((s,i)=>s+i.qty,0);
  }

  function renderCart() {
    const body = document.getElementById('cartBody');
    const foot = document.getElementById('cartFoot');
    const total = cart.reduce((s,i) => s+i.price*i.qty, 0);
    document.getElementById('cartTotal').textContent = '₹' + total.toLocaleString('en-IN');
    if (cart.length === 0) {
      body.innerHTML = '<div class="cart-empty"><div class="ei"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg></div><p>Cart is empty.<br/>Add some sarees!</p></div>';
      foot.style.display = 'none'; return;
    }
    foot.style.display = 'block';
    body.innerHTML = cart.map(item => `
      <div class="cart-item">
        ${item.img ? `<img class="ci-img" src="${item.img}" alt="${item.name}"/>` : `<div class="ci-img" style="display:flex;align-items:center;justify-content:center;font-size:1.8rem;background:#f5f5f5;">${item.emoji||'🥻'}</div>`}
        <div class="ci-info">
          <div class="ci-name">${item.name}</div>
          <div class="ci-meta">${item.category}${item.size && item.size !== 'N/A' ? ' · Size ' + item.size : ''}</div>
          <div class="ci-price">₹${(item.price * item.qty).toLocaleString('en-IN')}</div>
          <div class="ci-qty">
            <button class="qty-btn" onclick="updateQty('${item.id}',-1)">−</button>
            <span class="qty-val">${item.qty}</span>
            <button class="qty-btn" onclick="updateQty('${item.id}',1)">+</button>
          </div>
        </div>
        <button class="ci-remove" onclick="removeItem('${item.id}')" aria-label="Remove">✕</button>
      </div>
    `).join('');
  }

  function openCart() {
    document.getElementById('cartDrawer').classList.add('open');
    document.getElementById('cartOverlay').classList.add('show');
  }
  function closeCart() {
    document.getElementById('cartDrawer').classList.remove('open');
    document.getElementById('cartOverlay').classList.remove('show');
  }

  /* ── ORDER ── */
  function generateOrderId() {
    const d = new Date();
    return 'KVB-' + d.getFullYear().toString().slice(2) + String(d.getMonth()+1).padStart(2,'0') + String(d.getDate()).padStart(2,'0') + '-' + (Math.floor(Math.random()*9000)+1000);
  }

  function placeOrder() {
    if (!cart.length) return;
    currentOrderId = generateOrderId();
    const total = cart.reduce((s,i)=>s+i.price*i.qty,0);
    document.getElementById('orderIdDisplay').textContent = currentOrderId;
    document.getElementById('orderTotalDisplay').textContent = '₹' + total.toLocaleString('en-IN');
    document.getElementById('orderSummaryLines').innerHTML = cart.map((item,idx) => `
      <div class="order-line">
        <div class="oname">${idx+1}. ${item.name}<br/><span class="oqty">${item.category}${item.size!=='N/A'?' · Size '+item.size:''} × ${item.qty}</span></div>
        <div class="oprice">₹${(item.price*item.qty).toLocaleString('en-IN')}</div>
      </div>`).join('');
    closeCart();
    document.getElementById('orderModal').classList.add('show');
  }

  function closeOrderModal() {
    document.getElementById('orderModal').classList.remove('show');
    openCart();
  }

  function copyOrderId() {
    navigator.clipboard.writeText(currentOrderId).then(() => {
      const btn = document.querySelector('.copy-btn');
      btn.textContent = '✅ Copied!';
      setTimeout(() => btn.textContent = '📋 Copy ID', 2000);
    });
  }

  function sendOrderWA() {
    const now = new Date();
    const total = cart.reduce((s,i)=>s+i.price*i.qty,0);
    const lines = cart.map((item,i) => `  ${i+1}. ${item.name} (${item.category}${item.size!=='N/A'?' Size '+item.size:''}) × ${item.qty} — ₹${(item.price*item.qty).toLocaleString('en-IN')}`).join('\n');
    const msg = `🛍️ *New Order — KVB Sarees*\n\n📋 *Order ID:* ${currentOrderId}\n📅 *Date:* ${now.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}\n\n🧵 *Items:*\n${lines}\n\n💰 *Total: ₹${total.toLocaleString('en-IN')}*\n\nPlease confirm my order. Thank you! 🙏`;
    window.open(`https://wa.me/${OWNER_WA}?text=${encodeURIComponent(msg)}`, '_blank', 'noopener');
    cart = []; saveCart(); renderCart();
    document.getElementById('cartBadge').textContent = '0';
    document.getElementById('orderModal').classList.remove('show');
  }

  document.addEventListener('keydown', e => { if (e.key==='Escape') { closeDetail(); closeCart(); } });
